def permute_swap(nums):
    result = []
    n = len(nums)

    def backtrack(start):
        if start == n:
            result.append(nums[:])                     # completed permutation
            return
        for i in range(start, n):
            nums[start], nums[i] = nums[i], nums[start]  # swap into place
            backtrack(start + 1)
            nums[start], nums[i] = nums[i], nums[start]  # swap back

    backtrack(0)
    return result

