import java.util.*;

public class Main {
    static List<List<Integer>> permuteSwap(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        backtrack(nums, 0, result);
        return result;
    }
    static void backtrack(int[] nums, int start, List<List<Integer>> result) {
        if (start == nums.length) {
            List<Integer> perm = new ArrayList<>();
            for (int x : nums) perm.add(x);
            result.add(perm);                              // completed permutation
            return;
        }
        for (int i = start; i < nums.length; i++) {
            swap(nums, start, i);                           // swap into place
            backtrack(nums, start + 1, result);
            swap(nums, start, i);                           // swap back
        }
    }
    static void swap(int[] a, int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }
}

